// Created: 2026-09-23

/**
 * Unit tests for the two PostToolUse[Skill] hooks bound to /ork:expect:
 * fingerprint-saver (#1191) and snapshot-recorder (M125 #6), sweep T1.
 *
 * CC sends tool_input.skill as `ork:expect` (plugin prefix included) and the
 * tool result as `tool_response`, not `tool_output`. The bare-name match and
 * tool_output read meant both hooks never fired on a real payload.
 */

import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { execFileSync } from 'node:child_process';
import {
  mkdtempSync,
  rmSync,
  mkdirSync,
  writeFileSync,
  chmodSync,
  existsSync,
} from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

import { fingerprintSaver } from '../../../posttool/expect/fingerprint-saver.js';
import { expectSnapshotRecorder } from '../../../posttool/expect/snapshot-recorder.js';
import { createTestContext } from '../../fixtures/test-context.js';
import type { HookInput } from '../../../types.js';

let workspace: string;
let pluginRoot: string;
let testCtx: ReturnType<typeof createTestContext>;
let markerFile: string;

const PASS_OUTPUT = [
  'STEP_START|s1|open page',
  'STEP_DONE|s1|ok',
  'RUN_COMPLETED|passed|1 passed',
  'ROUTE|/settings',
  'ARIA|{"role":"main"}',
].join('\n');

beforeEach(() => {
  workspace = mkdtempSync(join(tmpdir(), 'ork-expect-proj-'));
  pluginRoot = mkdtempSync(join(tmpdir(), 'ork-expect-plugin-'));
  markerFile = join(pluginRoot, 'fingerprint-saved.marker');

  // Stub fingerprint.sh: `bash fingerprint.sh save` touches the marker.
  const scriptDir = join(pluginRoot, 'skills', 'expect', 'scripts');
  mkdirSync(scriptDir, { recursive: true });
  const script = join(scriptDir, 'fingerprint.sh');
  writeFileSync(script, `#!/usr/bin/env bash\ntouch "${markerFile}"\n`);
  chmodSync(script, 0o755);

  // Two commits so snapshot-recorder's `git rev-parse HEAD~1` resolves.
  try {
    execFileSync('git', ['init'], { cwd: workspace, stdio: 'pipe' });
    writeFileSync(join(workspace, 'a.txt'), '1');
    execFileSync('git', ['add', '.'], { cwd: workspace, stdio: 'pipe' });
    execFileSync('git', ['commit', '-m', 'one', '--no-gpg-sign'], { cwd: workspace, stdio: 'pipe' });
    writeFileSync(join(workspace, 'b.txt'), '2');
    execFileSync('git', ['add', '.'], { cwd: workspace, stdio: 'pipe' });
    execFileSync('git', ['commit', '-m', 'two', '--no-gpg-sign'], { cwd: workspace, stdio: 'pipe' });
  } catch {
    /* git unavailable: snapshot test will fail loudly, not silently skip */
  }

  process.env.CLAUDE_PLUGIN_ROOT = pluginRoot;
  process.env.CLAUDE_PROJECT_DIR = workspace;
  testCtx = createTestContext();
});

afterEach(() => {
  delete process.env.CLAUDE_PLUGIN_ROOT;
  delete process.env.CLAUDE_PROJECT_DIR;
  try {
    rmSync(workspace, { recursive: true, force: true });
    rmSync(pluginRoot, { recursive: true, force: true });
  } catch {
    /* best-effort */
  }
});

function makeExpectInput(skill: string, toolResponse: unknown): HookInput {
  return {
    tool_name: 'Skill',
    session_id: 'sid-test',
    tool_input: { skill } as Record<string, unknown>,
    tool_response: toolResponse,
    project_dir: workspace,
  };
}

describe('fingerprintSaver', () => {
  it('saves on the real CC payload: skill "ork:expect" + tool_response string', async () => {
    const r = await fingerprintSaver(makeExpectInput('ork:expect', PASS_OUTPUT), testCtx);
    expect(existsSync(markerFile)).toBe(true);
    const out = r.hookSpecificOutput as { additionalContext?: string } | undefined;
    expect(out?.additionalContext).toContain('Fingerprint saved');
  });

  it('stays silent when the run did not pass', async () => {
    const r = await fingerprintSaver(
      makeExpectInput('ork:expect', 'RUN_COMPLETED|failed|0 passed'),
      testCtx,
    );
    expect(existsSync(markerFile)).toBe(false);
    expect(r.hookSpecificOutput).toBeUndefined();
  });

  it('stays silent for a different skill', async () => {
    const r = await fingerprintSaver(makeExpectInput('ork:cover', PASS_OUTPUT), testCtx);
    expect(existsSync(markerFile)).toBe(false);
    expect(r.hookSpecificOutput).toBeUndefined();
  });
});

describe('expectSnapshotRecorder', () => {
  it('writes a snapshot on the real CC payload: skill "ork:expect" + tool_response', async () => {
    const r = await expectSnapshotRecorder(makeExpectInput('ork:expect', PASS_OUTPUT), testCtx);
    const dir = join(workspace, '.claude', 'state', 'expect-snapshots', 'settings');
    expect(existsSync(dir)).toBe(true);
    const out = r.hookSpecificOutput as { additionalContext?: string } | undefined;
    expect(out?.additionalContext).toContain('ARIA snapshot recorded');
  });

  it('stays silent when ROUTE/ARIA tags are absent', async () => {
    const r = await expectSnapshotRecorder(
      makeExpectInput('ork:expect', 'RUN_COMPLETED|passed|1 passed'),
      testCtx,
    );
    expect(r.hookSpecificOutput).toBeUndefined();
    expect(existsSync(join(workspace, '.claude', 'state', 'expect-snapshots'))).toBe(false);
  });
});
